def min_changes(n: int, k: int) -> int:
    if n & k != k:
        return -1  # k needs a bit that n lacks; bits cannot be turned on
    return bin(n ^ k).count("1")  # each differing bit is one clear operation

from math import gcd


def max_gcd_sum(nums: list[int], k: int) -> int:
    prefix = [0]
    for x in nums:
        prefix.append(prefix[-1] + x)
    best = 0
    groups = []  # (gcd value, leftmost start) for subarrays ending at r, newest start first
    for r, x in enumerate(nums):
        updated = [(x, r)]
        for g, start in groups:
            ng = gcd(g, x)
            if ng == updated[-1][0]:
                updated[-1] = (ng, start)  # same gcd: keep the further left start
            else:
                updated.append((ng, start))
        groups = updated
        for g, start in groups:
            if r - start + 1 >= k:
                best = max(best, (prefix[r + 1] - prefix[start]) * g)
    return best

def substring_xor_queries(s: str, queries: list[list[int]]) -> list[list[int]]:
    n = len(s)
    where = {}  # value -> [left, right] of its shortest, leftmost occurrence
    for left in range(n):
        if s[left] == "0":
            if 0 not in where:
                where[0] = [left, left]
            continue
        value = 0
        for right in range(left, min(n, left + 30)):
            value = value * 2 + (s[right] == "1")
            if value not in where:
                where[value] = [left, right]
    missing = [-1, -1]
    return [list(where.get(a ^ b, missing)) for a, b in queries]

