def minimum_time(power: list[int]) -> int:
    n = len(power)
    INF = float("inf")
    dp = [INF] * (1 << n)
    dp[0] = 0
    for mask in range(1 << n):
        days = dp[mask]
        if days == INF:
            continue
        gain = bin(mask).count("1") + 1  # one more than the monsters already defeated
        for i in range(n):
            if not mask & (1 << i):
                nxt = mask | (1 << i)
                cost = days + (power[i] + gain - 1) // gain  # ceiling division
                if cost < dp[nxt]:
                    dp[nxt] = cost
    return dp[-1]

def ways_to_reach_target(target: int, types: list[list[int]]) -> int:
    MOD = 10**9 + 7
    dp = [0] * (target + 1)
    dp[0] = 1
    for count, marks in types:
        new = [0] * (target + 1)
        drop = (count + 1) * marks  # the term that leaves the window
        for s in range(target + 1):
            value = dp[s]
            if s >= marks:
                value += new[s - marks]
            if s >= drop:
                value -= dp[s - drop]
            new[s] = value % MOD
        dp = new
    return dp[target]

