import heapq
from collections import defaultdict


class FileSharing:
    def __init__(self, m: int):
        self.m = m
        self.next_id = 1          # smallest id never handed out
        self.free_ids = []        # min heap of ids released by leave
        self.chunks_of = {}       # user id -> set of chunk ids
        self.owners = defaultdict(set)  # chunk id -> set of user ids

    def join(self, ownedChunks: list[int]) -> int:
        if self.free_ids:
            uid = heapq.heappop(self.free_ids)
        else:
            uid = self.next_id
            self.next_id += 1
        self.chunks_of[uid] = set(ownedChunks)
        for c in ownedChunks:
            self.owners[c].add(uid)
        return uid

    def leave(self, userID: int) -> None:
        for c in self.chunks_of.pop(userID, ()):
            self.owners[c].discard(userID)
        heapq.heappush(self.free_ids, userID)

    def request(self, userID: int, chunkID: int) -> list[int]:
        result = sorted(self.owners[chunkID])
        if result:
            self.owners[chunkID].add(userID)
            self.chunks_of[userID].add(chunkID)
        return result

