def maximum_prime_difference(nums: list[int]) -> int:
    # sieve of Eratosthenes up to 100
    is_prime = [False, False] + [True] * 99
    for p in range(2, 11):
        if is_prime[p]:
            for q in range(p * p, 101, p):
                is_prime[q] = False
    left = 0
    while not is_prime[nums[left]]:
        left += 1
    right = len(nums) - 1
    while not is_prime[nums[right]]:
        right -= 1
    return right - left

