def find_valid_split(nums: List[int]) -> int:
    # primes up to 1000 are enough to factor any value <= 10^6
    limit = 1000
    sieve = bytearray([1]) * (limit + 1)
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            sieve[p * p::p] = bytearray(len(sieve[p * p::p]))

    factors = []          # distinct primes of each element
    last = {}             # prime -> last index where it divides an element
    for idx, value in enumerate(nums):
        fs = []
        for p in primes:
            if p * p > value:
                break
            if value % p == 0:
                fs.append(p)
                while value % p == 0:
                    value //= p
        if value > 1:
            fs.append(value)
        for p in fs:
            last[p] = idx
        factors.append(fs)

    reach = 0
    for i in range(len(nums) - 1):
        for p in factors[i]:
            if last[p] > reach:
                reach = last[p]
        if reach == i:
            return i
    return -1

