def find_max_form(strs: List[str], m: int, n: int) -> int:
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for s in strs:
        zeros = s.count("0")
        ones = len(s) - zeros
        # iterate capacities downward so this string is used at most once
        for i in range(m, zeros - 1, -1):
            row, prev = dp[i], dp[i - zeros]
            for j in range(n, ones - 1, -1):
                cand = prev[j - ones] + 1
                if cand > row[j]:
                    row[j] = cand
    return dp[m][n]

