def min_distance(word1: str, word2: str) -> int:
    m, n = len(word1), len(word2)
    prev = [0] * (n + 1)
    for i in range(1, m + 1):
        cur = [0] * (n + 1)
        c = word1[i - 1]
        for j in range(1, n + 1):
            if c == word2[j - 1]:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = cur[j - 1] if cur[j - 1] > prev[j] else prev[j]
        prev = cur
    lcs = prev[n]
    return m + n - 2 * lcs

def max_sum_bst(root: Optional[TreeNode]) -> int:
    INF = float("inf")
    best = 0
    info = {None: (True, INF, -INF, 0)}   # node -> (is_bst, min, max, sum)
    stack = [(root, False)] if root else []
    while stack:
        node, done = stack.pop()
        if not done:
            stack.append((node, True))
            if node.right:
                stack.append((node.right, False))
            if node.left:
                stack.append((node.left, False))
            continue
        lb, lmin, lmax, lsum = info.pop(node.left) if node.left else info[None]
        rb, rmin, rmax, rsum = info.pop(node.right) if node.right else info[None]
        if lb and rb and lmax < node.val < rmin:
            total = lsum + rsum + node.val
            best = max(best, total)
            info[node] = (True, min(lmin, node.val), max(rmax, node.val), total)
        else:
            info[node] = (False, 0, 0, 0)
    return best

