def smallest_sufficient_team(req_skills: List[str], people: List[List[str]]) -> List[int]:
    m = len(req_skills)
    bit = {s: i for i, s in enumerate(req_skills)}
    masks = []
    for skills in people:
        mk = 0
        for s in skills:
            mk |= 1 << bit[s]
        masks.append(mk)
    # people grouped by each skill they own (identical masks kept once)
    by_skill = [[] for _ in range(m)]
    seen = set()
    for idx, mk in enumerate(masks):
        if mk == 0 or mk in seen:
            continue
        seen.add(mk)
        for b in range(m):
            if mk >> b & 1:
                by_skill[b].append((idx, mk))

    full = (1 << m) - 1
    INF = float("inf")
    size = [INF] * (full + 1)
    pick = [-1] * (full + 1)
    size[0] = 0
    for mask in range(1, full + 1):
        low = (mask & -mask).bit_length() - 1      # lowest skill still needed
        best, who = INF, -1
        for idx, mk in by_skill[low]:
            c = size[mask & ~mk]
            if c < best:
                best, who = c, idx
        size[mask] = best + 1
        pick[mask] = who

    team, mask = [], full
    while mask:
        p = pick[mask]
        team.append(p)
        mask &= ~masks[p]
    return team

