def build_wall(height: int, width: int, bricks: List[int]) -> int:
    MOD = 10 ** 9 + 7
    rows = []
    # enumerate rows as bitmasks of inner joint positions
    stack = [(0, 0)]                       # (filled width, joint mask)
    while stack:
        filled, mask = stack.pop()
        for b in bricks:
            nxt = filled + b
            if nxt == width:
                rows.append(mask)
            elif nxt < width:
                stack.append((nxt, mask | (1 << nxt)))
    if not rows:
        return 0
    compat = [[j for j, b in enumerate(rows) if a & b == 0] for a in rows]
    ways = [1] * len(rows)
    for _ in range(height - 1):
        ways = [sum(ways[j] for j in nbrs) % MOD for nbrs in compat]
    return sum(ways) % MOD

