def outer_trees(trees: List[List[int]]) -> List[List[int]]:
    def cross(o, a, b):
        # > 0: counter clockwise turn o -> a -> b, < 0: clockwise, 0: collinear
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    points = sorted(map(tuple, trees))
    if len(points) <= 2:
        return [list(p) for p in points]

    def chain(seq):
        stack = []
        for p in seq:
            # Pop only strictly clockwise turns so collinear boundary points survive.
            while len(stack) >= 2 and cross(stack[-2], stack[-1], p) < 0:
                stack.pop()
            stack.append(p)
        return stack

    hull = set(chain(points)) | set(chain(reversed(points)))
    return [list(p) for p in hull]

