def evaluate(s: str, knowledge: List[List[str]]) -> str:
    lookup = {key: value for key, value in knowledge}
    out = []
    i, n = 0, len(s)
    while i < n:
        if s[i] == "(":
            close = s.index(")", i)          # brackets never nest
            out.append(lookup.get(s[i + 1:close], "?"))
            i = close + 1
        else:
            # copy the run of plain letters up to the next bracket in one slice
            nxt = s.find("(", i)
            if nxt == -1:
                nxt = n
            out.append(s[i:nxt])
            i = nxt
    return "".join(out)

