def next_larger_nodes(head: Optional[ListNode]) -> List[int]:
    values = []
    while head:
        values.append(head.val)
        head = head.next
    answer = [0] * len(values)
    waiting = []                 # indices whose next larger value is unknown
    for i, v in enumerate(values):
        while waiting and values[waiting[-1]] < v:
            answer[waiting.pop()] = v
        waiting.append(i)
    return answer

